package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSwDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Kusikia Jogoo au Punda", "Ewe Mwenyezi Mungu, nakuomba fadhila zako (jogoo). - Najikinga kwa Mwenyezi Mungu na Shet'ani aliyelaaniwa (punda).", "Akisikia jogoo anaomba fadhila ya Mwenyezi Mungu; akisikia sauti ya punda jikinge na Shetani.", "Jogoo anaona malaika na punda anaona shetani."),
        "dua_something_liked" to DuaText("Kuona Kitu cha Kupendeza (Dhidi ya Jicho Ovu)", "Alivyopenda Mwenyezi Mungu. Ewe Mwenyezi Mungu, ibariki.", "Unapoona kitu cha kupendeza cha mtu fulani, omba baraka.", "Kuomba baraka huzuia jicho baya."),
        "dua_sell_buy_debt_repaid" to DuaText("Wakati wa Kulipa Deni", "Mwenyezi Mungu akubariki katika familia yako na mali yako.", "Kwa mkopeshaji wakati wa kulipa deni.", "Marejesho ya mkopo ni shukrani na marejesho."),
        "dua_talbiyah" to DuaText("Talbiyah", "Mimi hapa, ewe Mwenyezi Mungu, niko hapa. Mimi hapa, Huna mshirika, mimi hapa. Hakika sifa zote, baraka na ufalme ni Zako. Huna mshirika.", "Kwa sauti baada ya kuingia ihram.", "Nembo ya Hajj na Umrah."),
        "dua_yamani_hajar" to DuaText("Baina ya Rukn Yamani na Hajar Aswad", "Mola wetu Mlezi, tupe mema duniani na Akhera mema, na utulinde na adhabu ya Moto.", "Katika tawaf, kati ya Kona ya Yemeni na Jiwe Jeusi.", "Mtume ﷺ alikariri haya mahali hapa katika tawaf."),
        "dua_safa_marwa" to DuaText("Juu ya Safa na Marwah", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, peke yake, asiye na mshirika. Ufalme ni wake, na sifa njema ni zake, na Yeye ni Muweza wa kila kitu. Hapana apasae kuabudiwa kwa haki ila Mwenyezi Mungu peke yake; Alitimiza ahadi yake, akamsaidia mja Wake na peke yake akawashinda makundi.", "Kupanda Safa na kuelekea Qiblah (mara tatu).", "Dhikr ya Mtume ﷺ juu ya Safa na Marwah."),
        "dua_arafah" to DuaText("Dua Bora ya Siku ya Arafah", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, peke yake, asiye na mshirika. Ufalme ni wake, na sifa njema ni zake, na Yeye ni Muweza wa kila kitu.", "Siku ya Arafa - dua bora.", "Dua bora ni dua ya Siku ya Arafa, na maneno bora ni haya."),
        "dua_takbeer_tashreeq" to DuaText("Takbeer-e-Tashreeq", "Mwenyezi Mungu ndiye Mkubwa, Mwenyezi Mungu ndiye Mkuu. Hapana mungu ila Mwenyezi Mungu. Mwenyezi Mungu ndiye Mkubwa, Mwenyezi Mungu ndiye Mkubwa, na sifa njema zote ni za Mwenyezi Mungu.", "Baada ya kila swala ya faradhi kuanzia Alfajiri ya 9 Dhul-Hijjah hadi Alasiri ya 13 Dhul-Hijjah.", "Imepokewa kutoka kwa Ali na Ibn Mas'ud (RA) - wajib kwa mujibu wa Mahanafi."),
        "dua_zamzam" to DuaText("Kunywa Zamzam", "Ewe Mwenyezi Mungu, nakuomba elimu yenye manufaa, riziki nyingi na tiba ya kila ugonjwa.", "Unapokunywa Zamzam, fanya dua kwa chochote unachokusudia.", "Zamzam ni kwa chochote kinachonywewa (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Kutafakari Uumbaji", "Mola wetu, hukuumba haya yote bure. Umetakasika, basi tulinde na adhabu ya Moto.", "Dua ya wanaotafakari kuumbwa kwa mbingu na ardhi.", "Dua ya watu wenye ufahamu (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Tulimsikia Mwitaji wa Imani", "Mola wetu Mlezi tumemsikia mwitaji akiita kwenye Imani akisema: Muaminini Mola wenu Mlezi, nasi tukaamini. Mola wetu Mlezi, tusamehe madhambi yetu, na utuondolee maovu yetu na utufishe pamoja na watu wema.", "Dua ya imani na kufa miongoni mwa watu wema.", "Dua ya msamaha na mwisho mwema."),
        "dua_q_atina_ma_waadtana" to DuaText("Utupe Uliyoahidi", "Mola wetu Mlezi, tupe uliyotuahidi kupitia Mitume wako na usitufedheheshe Siku ya Kiyama. Hakika wewe huvunji ahadi yako.", "Makimbilio ya fedheha Siku ya Kiyama.", "Kutafuta heshima huko Akhera."),
        "dua_q_israfana" to DuaText("Samehe Yaliyozidi Yetu", "Mola wetu Mlezi, tughufirie madhambi yetu na upitaji mipaka katika mambo yetu, uifanye imara miguu yetu na utusaidie dhidi ya watu makafiri.", "Dua ya maswahaba wa Mitume waliotangulia.", "Dua ya uthabiti na msamaha."),
        "dua_q_jamiun_nas" to DuaText("Utawakusanya Wanadamu", "Mola wetu Mlezi, bila ya shaka utawakusanya watu Siku isiyo na shaka ndani yake. Hakika Mwenyezi Mungu havunji ahadi yake.", "Kuthibitisha yakini Siku ya Kiyama.", "Dua ya wale waliosimama imara katika elimu."),
        "dua_q_maash_shahidin" to DuaText("Tuandikie Miongoni mwa Mashahidi", "Mola wetu Mlezi, tumeamini, basi tuandikie miongoni mwa mashahidi.", "Dua ya wale walioitambua haki na kuamini.", "Dua ya kukubaliwa kwa imani ya mtu."),
        "dua_q_la_tajalna_zalimin" to DuaText("Si Pamoja na Madhalimu", "Mola wetu Mlezi, usituweke pamoja na watu madhalimu.", "Dua ya watu wa al-A'raf.", "Kimbilio kutokana na hatima ya madhalimu."),
        "dua_q_tawaffana_muslimin" to DuaText("Subira na Mauti kama Waislamu", "Mola wetu Mlezi, tumiminie subira na utufishe tukiwa Waislamu.", "Dua ya wachawi wa Firauni walipo amini.", "Uvumilivu katika majaribu na mwisho juu ya imani."),
        "dua_q_la_tajalna_fitnah" to DuaText("Si Majaribu kwa Wakandamizaji", "Kwa Mwenyezi Mungu tunamtegemea. Mola wetu Mlezi, usitufanye kuwa mtihani kwa watu madhalimu, na utuokoe kwa rehema yako na watu makafiri.", "Dua ya watu wa Musa (AS).", "Dua ya kuokoa kutoka kwa dhulma na madhalimu."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua ya Nuh (AS) kwa Msamaha", "Mola wangu Mlezi, najikinga Kwako nisikuombe yale nisiyoyajua. Na usiponisamehe na ukanirehemu nitakuwa miongoni mwa waliokhasirika.", "Dua ya toba ya Nabii Nuh (AS).", "Somo la kuuliza kwa adabu."),
        "dua_q_mudkhala_sidq" to DuaText("Kuingia na Kutoka kwa Ukweli", "Mola wangu Mlezi, niingize kwa haki, na nitoke kwa haki, na nipe kutoka kwako niwe na msaada.", "Kabla ya kuingia kazi mpya, nyumbani au mahali.", "Dua hiyo iliyofunzwa kwa Mtume ﷺ wakati wa Hijrah."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua ya Zakariya (AS) - Usiniache Peke Yangu", "Mola wangu Mlezi, usiniache peke yangu, na Wewe ndiye mbora wa warithi.", "Kwa wale wanaotafuta watoto.", "Kupitia dua hii Mwenyezi Mungu alimruzuku Yahya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Mahali Pema Kutua", "Mola wangu Mlezi, nijaalie nitue mahali palipobarikiwa, na Wewe ndiye mbora wa wanao leta.", "Wakati wa kuhamia nyumba mpya au kusimama mahali fulani - dua ya Nuh (AS).", "Dua ya baraka mahali papya."),
        "dua_q_amanna_faghfir" to DuaText("Tunaamini, Basi Utusamehe", "Mola wetu Mlezi, tumeamini, basi utusamehe na uturehemu, na Wewe ndiye Mbora wa wanaorehemu.", "Dua ya waja wema wa Mwenyezi Mungu.", "Dua ya kina ya msamaha na rehema."),
        "dua_q_isrif_jahannam" to DuaText("Epusha Adhabu ya Motoni", "Mola wetu Mlezi tuepushe na adhabu ya Jahannamu. hakika adhabu yake ni ya kudumu. Hakika hayo ni makazi maovu na makazi.", "Dua ya waja wa Mwingi wa Rehema ( ́Ibad ar-Rahman).", "Dua ya Qur'ani kwa ajili ya kukimbilia Motoni."),
        "dua_q_hab_li_hukman" to DuaText("Dua ya Ibrahim (AS) - Hekima na Jannah", "Mola wangu Mlezi, nipe hikima, na uniunganishe na watu wema, na unijaalie utukufu kwa watu wa baadae, na unijaalie niwe miongoni mwa warithi wa Pepo ya neema.", "Kuomba hekima, kundi la watu wema na Pepo.", "Dua ya kina ya Ibrahim (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Dua ya Lut (AS) - Okoa Familia Yangu", "Mola wangu Mlezi, niokoe mimi na ahali zangu kutokana na (matokeo ya) wanayoyafanya.", "Kulinda familia kutoka kwa mazingira mabaya.", "Ulinzi wa familia kutoka kwa uovu."),
        "dua_q_sulaiman_awzini" to DuaText("Dua ya Sulaiman (AS) kwa Shukrani", "Mola wangu Mlezi, niwezeshe kushukuru neema Yako uliyonineemesha mimi na wazazi wangu wawili, na nifanye vitendo vyema unavyoridhia, na uniingize kwa rehema yako miongoni mwa waja wako wema.", "Kwa uwezo wa kushukuru kwa baraka.", "Dua ya shukurani ya Sulayman (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Dua ya Musa (AS) - Nilijidhulumu Mwenyewe", "Mola wangu Mlezi, nimejidhulumu nafsi yangu, basi nisamehe.", "Toba ya haraka baada ya kosa.", "Mwenyezi Mungu alimsamehe Musa (AS)."),
        "dua_q_musa_najjini" to DuaText("Dua ya Musa (AS) - Niokoe kutoka kwa Wakandamizaji", "Mola wangu Mlezi niokoe na watu madhalimu.", "Wakati wa kuogopa wadhalimu.", "Dua ya Musa (AS) wakati wa kuondoka Misri."),
        "dua_q_lut_unsurni" to DuaText("Dua ya Lut (AS) - Msaada Dhidi ya Mafisadi", "Mola wangu Mlezi, nisaidie dhidi ya watu waharibifu.", "Kwa msaada dhidi ya wanaoeneza ufisadi.", "Dua ya wenye kusimama kidete juu ya haki."),
        "dua_q_hab_li_salihin" to DuaText("Dua ya Ibrahim (AS) kwa Mtoto Mwadilifu", "Mola wangu Mlezi, nipe (mtoto) miongoni mwa watu wema.", "Kuomba watoto waadilifu.", "Kupitia dua hii Isma'il (AS) ilikubaliwa."),
        "dua_q_wasita_kulla_shay" to DuaText("Dua ya Malaika Wenye Kiti cha Enzi", "Mola wetu Mlezi, Wewe umekizunguka kila kitu kwa rehema na elimu, basi wasamehe walio tubu na wakafuata njia yako, na uwakinge na adhabu ya Jahannamu.", "Malaika wanaobeba Arshi wanawaombea dua hii Waumini.", "Imesomwa kwa nia ya kuingizwa katika dua ya Malaika."),
        "dua_q_ikhwanina" to DuaText("Kwa Ndugu Zetu Waliotutangulia", "Mola wetu Mlezi, tusamehe sisi na ndugu zetu walio tutangulia kwa Imani, wala usitie kinyongo katika nyoyo zetu kwa walio amini. Mola wetu hakika wewe ni Mpole na Mwenye kurehemu.", "Dua kwa Waumini waliotangulia na kwa ajili ya nyoyo safi.", "Dua kwa Maswahaba watukufu (RA) na Waumini wa mwanzo."),
        "dua_q_alayka_tawakkalna" to DuaText("Juu yako tunakutegemea (Ibrahim AS)", "Mola wetu sisi tunakutegemea, Kwako tunaelekea na kwako ndio marejeo. Mola wetu Mlezi, usitufanye kuwa mtihani kwa makafiri na utusamehe. Mola wetu, hakika Wewe ndiye Mwenye nguvu, Mwenye hikima.", "Dua ya Ibrahim (AS) na maswahaba zake.", "Dua ya kumtegemea Mwenyezi Mungu na kurejea Kwake."),
        "dua_q_atmim_nurana" to DuaText("Kamilisha Nuru Yetu", "Mola wetu Mlezi, ututimizie nuru yetu na utusamehe. Hakika Wewe ni Muweza juu ya kila kitu.", "Dua ya waumini siku ya Qiyaamah.", "Kuomba mwanga juu ya Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua ya Asiya - Nyumba iliyoko Jannah", "Mola wangu Mlezi, nijengee nyumba Peponi karibu nawe, niokoe na Firauni na vitendo vyake, na niokoe na watu madhalimu.", "Dua ya Asiya, mke wa Firauni.", "Mwenyezi Mungu alimfanya kuwa ni mfano kwa waumini."),
        "dua_adhan_response" to DuaText("Kuitikia Adhana", "Hakuna nguvu wala uwezo ila kwa Mwenyezi Mungu.", "Rudia kile muadhini anasema; katika 'Hayya 'alas-salah' na 'Hayya 'alal-falah' wanasema hivi.", "Mwenye kujibu kutoka moyoni ataingia Peponi."),
        "dua_adhan_shahadah" to DuaText("Baada ya Shahada ya Muazzin", "Na pia nashuhudia ya kwamba hapana mola apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, Peke Yake, asiye na mshirika, na kwamba Muhammad ﷺ ni mja na Mtume Wake. Nimeridhika na Mwenyezi Mungu kama Mola, Muhammad ﷺ kama Mtume na Uislamu ni dini.", "Aliposikia ushuhuda wa imani wa muazini.", "Dhambi zake zimesamehewa."),
        "dua_istiftah_baid" to DuaText("Dua ya Ufunguzi: Nitenge na Madhambi", "Ewe Mwenyezi Mungu niepushe na dhambi zangu kama ulivyoiweka mashariki na magharibi. Ewe Mwenyezi Mungu nisafishe madhambi kama vile nguo nyeupe inavyosafishwa na uchafu. Ewe Mwenyezi Mungu, nioshe dhambi zangu kwa maji, theluji na mvua ya mawe.", "Baada ya takbir ya ufunguzi (inaweza pia kusemwa badala ya Sana).", "Mtume ﷺ alisoma hivi baina ya takbir na kisomo."),
        "dua_hamdan_kathiran" to DuaText("Sifa Nyingi Baada Ya Rukuu", "Mola wetu Mlezi, sifa njema ni Zako - sifa tele, safi na zenye baraka.", "Baada ya kuinuka kutoka kwenye rukuu, pamoja na 'Rabbana lakal-hamd'.", "Malaika zaidi ya thelathini walikuwa wanakimbia kuwa wa kwanza kuirekodi."),
    )
}
